async function renderActive(){const tab=activeTab();if(!tab)return;if(tab.kind==='report'){await renderReportTab(tab);return;}++loadingGeneration;try{if(tab.page==='home')home();else if(tab.page==='customers')await center('customer');else if(tab.page==='vendors')await center('vendor');else if(tab.page==='accounts')await accounts();else if(tab.page==='items')items();else if(tab.page==='invoice')createDocument(true);else if(tab.page==='bill')createDocument(false);else if(tab.page==='receive')payments(true);else if(tab.page==='pay')payments(false);else if(tab.page==='journal')journal();else if(tab.page==='reconcile')await reconcile();else if(tab.page==='bank')await bankTransactions();else if(tab.page==='budgets')budgets();else if(tab.page==='purchase')stock(true);else if(tab.page==='sale')stock(false);else if(tab.page==='settings')settings();}catch(error){$('#workpaper').replaceChildren(E('div',{class:'report-error'},error.message,E('br'),nativeButton('Retry',renderActive)));notice(error.message,true);}}
